def dfs(vertex, parent, label, current, graph):
    if graph[vertex][label] != current:
        return 0
    res = current - graph[vertex][label] + graph[vertex][label] % 2
    for child in graph[vertex]:
        if child != parent:
            res += dfs(child, vertex, label, res, graph)
            if graph[vertex][label] == graph[child][label]:
                res = res + graph[child][label] % 2
            else:
                res = res - graph[child][label] % 2
    return res % 2

