def find_bus(people, buses):
    people.sort(key=lambda x: (x[0], x[1]))
    buses.sort(key=lambda x: x[2])

    stops = defaultdict(list)
    for person, (start, end, time_i) in people:
        for bus in buses:
            if start > end:
                break
            elif bus[0] <= start <= bus[1]:
                bus[2][0].append(person)
            bus[2][1].append((time_i, person))

    for time, people in buses[0].values():
        bus_id = time[2]
        people.sort(key=operator.itemgetter(0))

        for person, (_, time_i) in people:
            if len(stops[time_i][bus_id]) > 0 and person in stops[time_i][bus_id]:
                continue

            answer = []
            while len(stops[time_i][bus_id]) > 0:
                person = stops[time_i][bus_id][0]
                ans_service = time_i - buses[0][0][2][-1][0]
                if ans_service <= ends:
                    answer.append(buses[0][0][1])
                    stops[ans_service][bus_id].remove(person)

            buses[0][2].append((ans_service, person))
            break

    return [answer[0] if len(ans) > 0 else -1 for (ans, ends) in buses[0].values()]

