from itertools import combinations

MOD = 998244353

def factorial(n):
    return product(range(1, n + 1))

def product(lst):
    """Return factorial list of digits"""
    if len(lst) <= 1:
        return lst
    else:
        current = []
        for lst_digit in lst:
            newList = []
            for digit in range(1, 10):
                padd = str(digit)
                leftpad = str(lst_digit) + padd * (lst_digit - len(str(digit)))
                if int(leftpad) <= n:
                    newList.extend(list(leftpad))
                    current.extend([
                        product(range(0, lst_digit)),
                        map(lambda x: int(leftpad) + x, product(range(0, lst_digit))),
                        map(lambda x: int(padd) + str(x), product(range(0, lst_digit)))
                    ])
    current.extend([
        product(range(lst_digit)),
        map(lambda x: int(str(lst_digit)) + x,
            product(range(0, lst_digit)))
    ])
    if list(current) == []:
        return [n]
    else:
        return [x for x in current if x <= n]

def count_edges(S):
