def next_char(root, paths, letter, length):
    try:
        new_path = ''
        for i in range(length + 1):
            if i < len(paths) and i < len(letter):
                if paths[i] == letter[i]:  
                    new_path = new_path + letter[i]
                else:
                    return letter[i:i+1]
        return next_char(root, paths, letter, length) if len(paths) > len(letter) else 'a'
    except IndexError:
        return 'a'

# A function to find the parent of a root or a node in the Trie
def path_parent(root, node):
    for parent in node.parents:
        if parent.is_end:
            return parent.depth
    return -1

# A Trie class for storing the paths of characters and their directions
class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, paths, length, letter):
        for path in paths:
            self.insert_char(path, length, letter)

    def insert_char(self, char, length, letter):
        if char in self.root.trie:
            for parent in self.root.trie[char].parents:
                if length + 1 == parent.depth:
                    parent.is_end = True
                    break
        else:
            self.root.trie[char] = Node()

        self.root.trie[char].add_child(parent)

