MOD_VAL =  998244353

class Solution:

    def __init__(self):
        self.existed_permutations = {}

    def lcm(self, a, b):
        g = 2
        g = gcd(gcd(a, b), 1)
        return lcm(a, b) // g

    def gcd(self, a, b):
        return a if b == 0 else self.gcd(b, a % b)

    def reduce(self, g):
        n = len(g)
        for i in range(n):
            for j in range(i + 1, n):
                if g[i] == g[j]:
                    del g[j]
                    break
        return g

    def solve(self, n):
        grouping_permutations = [self.reduce(pow(len(self.existed_permutations), len(self.existed_permutations), MOD_VAL).split())
                                 for _ in self.existed_permutations]
        return self.lcm(grouping_permutations[0])
