def number_of_configurations(n, edges, dropped):
    count = [0] * n
    for i in range(1, n):
        count[edges[i-1]] += 1

    unique_counts = []
    for key, value in enumerate(count):
        if key == dropped:
            continue
        else:
            unique_counts.append(value)

