from collections import defaultdict

def detect_arbitrary_ring(graph, threshold):
    """
    Detects the hardariness of forming viable cycles of length >= k.
    """
    leaf_set = set()
    root = -1  # To keep track of the node against which we are looking

    def backtrack(node):
        leaf_set.add(node)
        for neighbor in graph[node]:
            if neighbor in leaf_set:
                continue
            if neighbor == root:
                raise ValueError
            if neighbor not in cycle_set:
                cycle_set.add(neighbor)
                try:
                    backtrack(neighbor)
                except ValueError:
                    cycle_set.remove(neighbor)
                    return

    graph_components = defaultdict(list)
    nodes = list(range(len(graph)))

    def cycle(n):
        # Recursively explore each branch.
        cycle_set = set()
        if n is root:
            raise ValueError
        cycle_set.add(n)
        while True:
            next_node = graph[n][0]
            if next_node == n:
                break
            n = next_node
            new_set = set()
            for j, a in enumerate(graph[n]):
                if a != n and j < len(graph[1]):
                    if a not in cycle_set and a != root and a not in new_set:
                        new_set.add(a)
                        new_set.update(graph[a])
                        if next_node is not 0:
                            n = next_node
                            break
            for new_node in new_set:
                if new_node < len(graph_components):
                    graph_components[new_node] = new_set
                    cycle(n)
                    break
        else:
            cycle_set.remove(n)
            graph_components[n] -= cycle_set

    cycle(root)
    for node, graph in graph_components.items():
        if len(graph) >= threshold:
            return 'YES'
    return 'NO'

