MOD = 998244353

def power(x, e):
    if e == 0:
        return 1
    else:
        return power(x, e // 2) * power(x, e % 2) % MOD

def num_faces(triangles):
    return sum(triangles, [])[-1]

def convex_hull(points):
    n = len(points)
    opposite = [j for j in range(n) if points[j][0] != points[num_faces(points)[:1][0]][0]]
    upper = upper_hull(points, opposite)
    lower = lower_hull(points, opposite)
    return (upper + lower)[1:-1]

def upper_hull(points, op):
    result = []
    left, right = 0, n - 1
    while True:
        while right < n and points[op[right]][1] >= points[left][1]:
            right += 1
        while right < n and points[op[left]][0] < points[op[right]][0] and points[op[right]][1] <= points[op[left]][1]:
            result.append(op[op[right]])
            right += 1
        if right >= n or points[op[left]][0] >= points[op[right]][0]:
            break
        result.append(op[op[left]])
        left, right = right, right + 1
    if len(result) + 1 == right and points[num_faces(points)[:1][0]][1] >= points[op[left]][1]:
        return result + [num_faces(points)[:1][0]]
    else:
        return [num_faces(points)[:1][0]] + result

def lower_hull(points, op):
    points_op = list(zip(*points[::-1]))[::-1]
    return convex_hull(points_op)

def triangulate(points):
    if len(points) <= 3:
        yield points
    else:
        line = convex_hull(points)
        for point in line:
            for other in triangulate(points + [point]):
                yield other + (point,) 

def main():
    N = int(input())
    points = [tuple(map(int, input().split())) for i in range(N)]
    triangles = list(triangulate(points))
    scores = [2**(num_faces(triangles) - len(triangles)) for triangles in triangles]
    print(sum(scores) % MOD)

if __name__ == "__main__":
    main()
