def calculate_sum_of_divisors(n):
    total_sum = 1  # Start with 1 because every number is divisible by 1
    for i in range(2, n):
        if n % i == 0:
            total_sum += i
    return total_sum + n

n = int(input())
if n > 2:
    print("%s\nUse Standard Input format" % calculate_sum_of_divisors(n))
